  [213513] = { "Apprendi una nuova abilità dopo aver usato ⟦Blessing of Freedom=Benedizione della Libertà⟧ per liberare altri dagli effetti che impediscono il movimento $N1 volte.", 0x8f7f61d9, "u" },
