  [213550] = { "Trasforma il bersaglio in un Odd Melon.", 0xa08bd2d0, "u" },
  [213552] = { "Accumulati e custoditi gelosamente dalla tribù di centauri Gelkis, si dice che concedano a chi li impugna la protezione degli spiriti della terra.", 0x91b0bfd8, "u" },
  [213553] = { "Accumulati e custoditi gelosamente dalla tribù di centauri Gelkis, si dice che concedano a chi li impugna la protezione degli spiriti della terra.", 0x37e4a853, "u" },
  [213554] = { "Mescola con le Tears of Theradras per creare un Elemental Salve in grado di purificare la corruzione.\nL'acqua è così cristallina che la fiala sembra vuota.", 0x4366cc37, "u" },
  [213558] = { "Versalo sugli oggetti corrotti per purificarli.\nUn potente unguento in grado di purificare una corruzione profonda.", 0x7de9b94a, "u" },
  [213562] = { "Cattura un insetto esotico e conservalo come esemplare.", 0x7c522522, "u" },
  [213564] = { "Rigenera $N1 mana in $D1.", 0x8bf8309d, "u" },
  [213583] = { "Sembra che il precedente proprietario abbia giocato con il fuoco una volta di troppo poco.", 0xff2707b7, "u" },
  [213594] = { "Provoca $N1 o più nemici con Challenging Roar e uccidine almeno uno. Dopo $N2 uccisioni, usa questo idolo per apprendere una nuova abilità.", 0xc6388a5d, "u" },
  [213599] = { "Concentrati sulla Visione per apprendere un nuovo incantesimo. Richiede uno sguardo fugace su una conoscenza corrotta.", 0x045217d4, "u" },
  [213632] = { "Combina i Partial Spell Notes raccolti in una pergamena che insegna un nuovo incantesimo d'incisione.\nUna pagina incompleta che somiglia alle pergamene che insegnano le abilità d'incisione. Ne mancano due terzi.", 0x44e70def, "u" },
  [213633] = { "Combina i Partial Spell Notes raccolti in una pergamena che insegna un nuovo incantesimo d'incisione.\nUna pagina incompleta che somiglia alle pergamene che insegnano le abilità d'incisione. Ne mancano due terzi.", 0x44e70def, "u" },
