  [213701] = { "Combina $N1 Strong Harpy Feather e $N2 Cloud Serpent Fang con $N3 ⟦Silken Thread=Filo di Seta⟧ per creare un Offering to the Wind Spirit.", 0xf5d79734, "u" },
  [213709] = { "Combina $N1 Strong Harpy Feather e $N2 Cloud Serpent Fang con $N3 ⟦Silken Thread=Filo di Seta⟧ per creare un Offering to the Wind Spirit.", 0xf5d79734, "u" },
  [213735] = { "Quest'aggeggio può pre-renderizzare oltre $N1 milioni di gigaflop di codeburst relazionali a bassa varianza. Wow!", 0xb431cb1e, "u" },
  [213736] = { "Questo nucleo di processore è incrostato di corrosione e di una sostanza nera e appiccicosa, ma attraverso la sporcizia riesci a malapena a distinguere un numero di modello e qualche parola illeggibile. Potrebbe servirti uno specialista per restaurarlo.", 0x71fa5f27, "u" },
